{"summary": "Verify output app structure, assets, and serve index via http", "security_risk": "LOW", "command": "set -n; 
# Existence checks
for p in /root/output/index.html /root/output/js/d3.v6.min.js /root/output/js/visualization.js /root/output/css/style.css /root/output/data/stock-descriptions.csv; do
  test -f "$p" || { echo "MISSING $p"; exit 1; }
done

echo "OK: core files exist"

# Data checks
echo -n "stock-descriptions rows: " && awk 'END{print NR-1}' /root/output/data/stock-descriptions.csv
echo -n "indiv-stock csv files: " && find /root/output/data/indiv-stock -maxdepth 1 -type f -name '*.csv' | wc -l

# Reference checks
grep -n "js/d3.v6.min.js" -n /root/output/index.html >/dev/null && echo "OK: index references d3"
grep -n "EMBEDDED_STOCK_DESCRIPTIONS_CSV" -n /root/output/js/visualization.js >/dev/null && echo "OK: embedded CSV fallback present"

# Quick server fetch check
pid=$(python3 -m http.server --directory /root/output 8000 >/tmp/oh_http.log 2>&1 & echo $!);
sleep 1;
curl -sSf http://127.0.0.1:8000/index.html | head -n 20;
kill $pid;
echo "OK: served index.html over http://127.0.0.1:8000/";
"}

