{"summary": "Create CSS for side-by-side layout, table styling, and tooltips", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
  --bg: #0b1220;
  --panel: #0f1b33;
  --text: #e7eefc;
  --muted: #a8b6d4;
  --border: rgba(255, 255, 255, 0.10);
  --shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  --selected: rgba(255, 255, 255, 0.12);
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  color: var(--text);
  background: radial-gradient(1200px 800px at 25% 20%, rgba(69, 120, 255, 0.20), transparent 55%),
              radial-gradient(900px 700px at 75% 30%, rgba(255, 153, 51, 0.12), transparent 55%),
              var(--bg);
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(10px);
  background: rgba(11, 18, 32, 0.70);
  border-bottom: 1px solid var(--border);
}

.app-header__inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 18px 18px 14px;
}

h1 {
  margin: 0;
  font-size: 20px;
  letter-spacing: 0.2px;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.app-main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 18px;

  display: flex;
  gap: 16px;
  align-items: stretch;
}

.panel {
  background: rgba(15, 27, 51, 0.78);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow);
  padding: 14px;
  min-height: 520px;
}

.panel--chart {
  flex: 1.1;
  min-width: 520px;
}

.panel--table {
  flex: 0.9;
  min-width: 420px;
}

.panel__title {
  display: flex;
  gap: 12px;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 10px;
}

.panel__title h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
  color: var(--text);
}

.hint {
  font-size: 12px;
  color: var(--muted);
}

.chart {
  width: 100%;
}

.chart svg {
  width: 100%;
  height: auto;
  display: block;
}

.legend-title {
  font-size: 12px;
  fill: var(--muted);
}

.legend-item text {
  font-size: 12px;
  fill: var(--text);
}

.bubble {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1;
}

.bubble.selected {
  stroke: rgba(255, 255, 255, 0.92);
  stroke-width: 2.5;
}

.bubble-label {
  font-size: 11px;
  font-weight: 700;
  fill: rgba(255, 255, 255, 0.95);
  pointer-events: none;
  user-select: none;
}

.table table {
  width: 100%;
  border-collapse: collapse;
}

.table thead th {
  position: sticky;
  top: 0;
  background: rgba(11, 18, 32, 0.90);
  border-bottom: 1px solid var(--border);
  padding: 10px 10px;
  text-align: left;
  font-size: 12px;
  color: var(--muted);
}

.table tbody td {
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding: 10px 10px;
  font-size: 13px;
  vertical-align: top;
}

.table tbody tr {
  cursor: pointer;
}

.table tbody tr:hover {
  background: rgba(255, 255, 255, 0.06);
}

.table tbody tr.selected {
  background: var(--selected);
  outline: 1px solid rgba(255, 255, 255, 0.18);
}

.mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

.right {
  text-align: right;
}

.tooltip {
  position: absolute;
  max-width: 320px;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s ease;
  z-index: 1000;
}

.tooltip.visible {
  opacity: 1;
}

.tooltip .ticker {
  font-weight: 800;
  letter-spacing: 0.2px;
}

.tooltip .muted {
  color: rgba(255, 255, 255, 0.75);
  font-size: 12px;
  margin-top: 3px;
}

@media (max-width: 1100px) {
  .app-main {
    flex-direction: column;
  }

  .panel--chart,
  .panel--table {
    min-width: 0;
  }
}
"}

