{"summary": "Create D3 v6 visualization logic for bubble chart and linked table", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */

(function () {
  const DATA_PATH = 'data/stock-descriptions.csv';

  const CHART_WIDTH = 720;
  const CHART_HEIGHT = 560;
  const CHART_MARGIN = { top: 18, right: 18, bottom: 18, left: 18 };

  const ETF_RADIUS = 18;

  const tooltip = d3.select('#tooltip');

  let selectedTicker = null;

  function parseNumber(v) {
    if (v == null) return null;
    const n = +String(v).trim();
    return Number.isFinite(n) ? n : null;
  }

  function formatMarketCap(v) {
    if (v == null) return '—';
    const abs = Math.abs(v);

    function fmt(num) {
      const s = num.toFixed(2);
      return s.endsWith('.00') ? s.slice(0, -3) : s;
    }

    if (abs >= 1e12) return `${fmt(v / 1e12)}T`;
    if (abs >= 1e9) return `${fmt(v / 1e9)}B`;
    if (abs >= 1e6) return `${fmt(v / 1e6)}M`;
    if (abs >= 1e3) return `${fmt(v / 1e3)}K`;
    return String(v);
  }

  function normalizeRow(d) {
    const ticker = (d.ticker || '').trim();
    const sector = (d.sector || '').trim() || 'Unknown';
    const fullName = (d['full name'] || '').trim();
    const marketCap = parseNumber(d.marketCap);
    const country = (d.country || '').trim();
    const website = (d.website || '').trim();

    const isETF = sector === 'ETF';

    return {
      ticker,
      sector,
      fullName,
      marketCap,
      country,
      website,
      isETF,
      hasTooltipData: !isETF && ticker !== '' && fullName !== '' && sector !== '' && marketCap != null && country !== '' && website !== ''
    };
  }

  function setSelectedKey(ticker) {
    selectedTicker = ticker;
    renderSelection();
  }

  let bubbleCircles = null;
  let tableRows = null;

  function renderSelection() {
    if (bubbleCircles) {
      bubbleCircles.classed('selected', d => d.ticker === selectedTicker);
    }

    if (tableRows) {
      tableRows.classed('selected', d => d.ticker === selectedTicker);

      const row = tableRows.filter(d => d.ticker === selectedTicker);
      if (!row.empty()) {
        const node = row.node();
        if (node && typeof node.scrollIntoView === 'function') {
          node.scrollIntoView({ block: 'nearest' });
        }
      }
    }
  }

  function showTooltip(event, d) {
    tooltip
      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .html(
        `<div class="ticker">${d.ticker}</div>` +
        `<div class="muted">${escapeHtml(d.fullName)}</div>` +
        `<div class="muted">Sector: ${escapeHtml(d.sector)}</div>`
      );

    positionTooltip(event);
  }

  function positionTooltip(event) {
    const padding = 12;
    const { clientX, clientY } = event;

    tooltip.style('left', (clientX + padding) + 'px');
    tooltip.style('top', (clientY + padding) + 'px');
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function buildLegend(svg, sectors, color) {
    const g = svg.append('g')
      .attr('class', 'legend')
      .attr('transform', `translate(${CHART_MARGIN.left + 6},${CHART_MARGIN.top + 6})`);

    g.append('text')
      .attr('class', 'legend-title')
      .attr('x', 0)
      .attr('y', 0)
      .attr('dy', '0.9em')
      .text('Sector');

    const item = g.selectAll('g.legend-item')
      .data(sectors)
      .join('g')
      .attr('class', 'legend-item')
      .attr('transform', (d, i) => `translate(0,${22 + i * 18})`);

    item.append('rect')
      .attr('x', 0)
      .attr('y', -10)
      .attr('width', 12)
      .attr('height', 12)
      .attr('rx', 3)
      .attr('fill', d => color(d))
      .attr('stroke', 'rgba(255,255,255,0.25)');

    item.append('text')
      .attr('x', 18)
      .attr('y', 0)
      .attr('dy', '0.12em')
      .text(d => d);
  }

  function buildBubbleChart(data) {
    const width = CHART_WIDTH;
    const height = CHART_HEIGHT;

    const svg = d3.select('#chart')
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('role', 'img')
      .attr('aria-label', 'Bubble chart of stocks clustered by sector');

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort(d3.ascending);

    const palette = [
      '#4e79a7', '#f28e2b', '#e15759', '#76b7b2', '#59a14f',
      '#edc948', '#b07aa1', '#ff9da7', '#9c755f', '#bab0ab'
    ];

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(palette.slice(0, sectors.length));

    const caps = data
      .filter(d => !d.isETF && d.marketCap != null)
      .map(d => d.marketCap)
      .sort((a, b) => a - b);

    const capMin = caps.length ? caps[0] : 1;
    const capMax = caps.length ? caps[caps.length - 1] : 1;

    const rScale = d3.scaleSqrt()
      .domain([capMin, capMax])
      .range([12, 56]);

    data.forEach(d => {
      d.r = d.isETF || d.marketCap == null ? ETF_RADIUS : rScale(d.marketCap);
    });

    buildLegend(svg, sectors, color);

    const cx = width / 2;
    const cy = height / 2 + 16;
    const ringR = Math.min(width, height) * 0.22;

    const sectorCenters = new Map();
    sectors.forEach((s, i) => {
      const angle = (-Math.PI / 2) + (2 * Math.PI * i) / sectors.length;
      sectorCenters.set(s, {
        x: cx + ringR * Math.cos(angle),
        y: cy + ringR * Math.sin(angle)
      });
    });

    const nodes = svg.append('g')
      .attr('transform', `translate(0,0)`)
      .selectAll('g.node')
      .data(data, d => d.ticker)
      .join('g')
      .attr('class', 'node')
      .attr('tabindex', 0)
      .attr('role', 'button')
      .attr('aria-label', d => `Select ${d.ticker}`)
      .on('click', (event, d) => {
        setSelectedKey(d.ticker);
      })
      .on('keydown', (event, d) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          setSelectedKey(d.ticker);
        }
      })
      .on('mousemove', (event, d) => {
        if (!d.hasTooltipData) return;
        positionTooltip(event);
      })
      .on('mouseover', (event, d) => {
        if (!d.hasTooltipData) return;
        showTooltip(event, d);
      })
      .on('mouseout', () => {
        hideTooltip();
      });

    bubbleCircles = nodes.append('circle')
      .attr('class', 'bubble')
      .attr('r', d => d.r)
      .attr('fill', d => color(d.sector));

    nodes.append('text')
      .attr('class', 'bubble-label')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .text(d => d.ticker);

    const simulation = d3.forceSimulation(data)
      .force('center', d3.forceCenter(cx, cy))
      .force('x', d3.forceX(d => sectorCenters.get(d.sector).x).strength(0.22))
      .force('y', d3.forceY(d => sectorCenters.get(d.sector).y).strength(0.22))
      .force('collide', d3.forceCollide(d => d.r + 1.6).iterations(2))
      .force('charge', d3.forceManyBody().strength(-6))
      .alpha(1)
      .alphaDecay(0.035);

    simulation.on('tick', () => {
      nodes.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    // Start with a stable initial placement: sector center + small deterministic offset.
    data
      .slice()
      .sort((a, b) => d3.ascending(a.ticker, b.ticker))
      .forEach((d, i) => {
        const c = sectorCenters.get(d.sector);
        const t = (i % 16) / 16;
        const a = 2 * Math.PI * t;
        d.x = c.x + 6 * Math.cos(a);
        d.y = c.y + 6 * Math.sin(a);
      });

    simulation.alpha(1).restart();

    // Background click clears selection.
    svg.on('click', (event) => {
      if (event.target === svg.node()) {
        selectedTicker = null;
        renderSelection();
      }
    });
  }

  function buildTable(data) {
    const container = d3.select('#table');

    const sorted = data.slice().sort((a, b) => {
      const aHas = a.marketCap != null;
      const bHas = b.marketCap != null;
      if (aHas && bHas) return d3.descending(a.marketCap, b.marketCap) || d3.ascending(a.ticker, b.ticker);
      if (aHas && !bHas) return -1;
      if (!aHas && bHas) return 1;
      return d3.ascending(a.ticker, b.ticker);
    });

    const table = container.append('table');

    table.append('thead')
      .append('tr')
      .selectAll('th')
      .data([
        'Ticker symbol',
        'Full company name',
        'Sector',
        'Market cap'
      ])
      .join('th')
      .text(d => d);

    const tbody = table.append('tbody');

    tableRows = tbody.selectAll('tr')
      .data(sorted, d => d.ticker)
      .join('tr')
      .attr('tabindex', 0)
      .on('click', (event, d) => {
        setSelectedKey(d.ticker);
      })
      .on('keydown', (event, d) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          setSelectedKey(d.ticker);
        }
      });

    tableRows.append('td')
      .attr('class', 'mono')
      .text(d => d.ticker);

    tableRows.append('td')
      .text(d => d.fullName);

    tableRows.append('td')
      .text(d => d.sector);

    tableRows.append('td')
      .attr('class', 'right mono')
      .text(d => formatMarketCap(d.marketCap));
  }

  function init() {
    d3.csv(DATA_PATH, normalizeRow)
      .then(data => {
        buildBubbleChart(data);
        buildTable(data);
        renderSelection();
      })
      .catch(err => {
        // eslint-disable-next-line no-console
        console.error(err);
        d3.select('#chart').append('div').style('color', '#ffb4b4').text('Failed to load data.');
      });

    window.addEventListener('scroll', hideTooltip, { passive: true });
  }

  init();
})();
"}

