        const node = row.node();
        if (node && typeof node.scrollIntoView === 'function') {
          node.scrollIntoView({ block: 'nearest' });
        }
      }
    }
  }

  function showTooltip(event, d) {
    tooltip
      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .html(
        `<div class="ticker">${d.ticker}</div>` +
        `<div class="muted">${escapeHtml(d.fullName)}</div>` +
        `<div class="muted">Sector: ${escapeHtml(d.sector)}</div>`
      );

    positionTooltip(event);
  }

  function positionTooltip(event) {
    const padding = 12;
    const { clientX, clientY } = event;

    tooltip.style('left', (clientX + padding) + 'px');
    tooltip.style('top', (clientY + padding) + 'px');
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function buildLegend(svg, sectors, color) {
    const g = svg.append('g')
      .attr('class', 'legend')
      .attr('transform', `translate(${CHART_MARGIN.left + 6},${CHART_MARGIN.top + 6})`);

    g.append('text')
      .attr('class', 'legend-title')
      .attr('x', 0)
      .attr('y', 0)
      .attr('dy', '0.9em')
      .text('Sector');

    const item = g.selectAll('g.legend-item')
      .data(sectors)
      .join('g')
      .attr('class', 'legend-item')
      .attr('transform', (d, i) => `translate(0,${22 + i * 18})`);

    item.append('rect')
      .attr('x', 0)
      .attr('y', -10)
      .attr('width', 12)
      .attr('height', 12)
      .attr('rx', 3)
      .attr('fill', d => color(d))
      .attr('stroke', 'rgba(255,255,255,0.25)');

    item.append('text')
      .attr('x', 18)
      .attr('y', 0)
      .attr('dy', '0.12em')
      .text(d => d);
  }

  function buildBubbleChart(data) {
    const width = CHART_WIDTH;
    const height = CHART_HEIGHT;

    const svg = d3.select('#chart')
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('role', 'img')
      .attr('aria-label', 'Bubble chart of stocks clustered by sector');

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort(d3.ascending);

    const palette = [
      '#4e79a7', '#f28e2b', '#e15759', '#76b7b2', '#59a14f',
      '#edc948', '#b07aa1', '#ff9da7', '#9c755f', '#bab0ab'
    ];

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(palette.slice(0, sectors.length));

    const caps = data
      .filter(d => !d.isETF && d.marketCap != null)
      .map(d => d.marketCap)
      .sort((a, b) => a - b);

    const capMin = caps.length ? caps[0] : 1;
    const capMax = caps.length ? caps[caps.length - 1] : 1;

    const rScale = d3.scaleSqrt()
      .domain([capMin, capMax])
      .range([12, 56]);

