    table.append('thead')
      .append('tr')
      .selectAll('th')
      .data([
        'Ticker symbol',
        'Full company name',
        'Sector',
        'Market cap'
      ])
      .join('th')
      .text(d => d);

    const tbody = table.append('tbody');

    tableRows = tbody.selectAll('tr')
      .data(sorted, d => d.ticker)
      .join('tr')
      .attr('tabindex', 0)
      .on('click', (event, d) => {
        setSelectedKey(d.ticker);
      })
      .on('keydown', (event, d) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          setSelectedKey(d.ticker);
        }
      });

    tableRows.append('td')
      .attr('class', 'mono')
      .text(d => d.ticker);

    tableRows.append('td')
      .text(d => d.fullName);

    tableRows.append('td')
      .text(d => d.sector);

    tableRows.append('td')
      .attr('class', 'right mono')
      .text(d => formatMarketCap(d.marketCap));
  }

  function init() {
    d3.csv(DATA_PATH, normalizeRow)
      .then(data => {
        buildBubbleChart(data);
        buildTable(data);
        renderSelection();
      })
      .catch(err => {
        // eslint-disable-next-line no-console
        console.error(err);
        d3.select('#chart').append('div').style('color', '#ffb4b4').text('Failed to load data.');
      });

    window.addEventListener('scroll', hideTooltip, { passive: true });
  }

  init();
})();
