  color: var(--text);
}

.hint {
  font-size: 12px;
  color: var(--muted);
}

.chart {
  width: 100%;
}

.chart svg {
  width: 100%;
  height: auto;
  display: block;
}

.legend-title {
  font-size: 12px;
  fill: var(--muted);
}

.legend-item text {
  font-size: 12px;
  fill: var(--text);
}

.bubble {
  stroke: rgba(255, 255, 255, 0.25);
